  updateScheduled(id: string, body: S.ChatScheduledPatchBody, options?: RequestOptions): Promise<S.ChatScheduled> {
    return this._http.request({ method: 'PATCH', path: `/v1/community/chat/scheduled/${seg(id)}`, body, options });
  }

  /**
   * Renomeia um agrupamento (exige `community.chat.manage` pela tabela de rotas).
   *
   * Troca o titulo do agrupamento da organizacao da sessao.
   *
   * `PATCH /v1/community/chat/sections/{id}`
   *
   * @param id Id do agrupamento
   * @param body Request body.
   * @param options Per-call overrides.
   */
